const items = $input.all();

return items.map((item, index) => {
  const sourceDoc = $('Start').itemMatching.json.Code_itemMatching_unknown(index).json;

  const filename = sourceDoc.filename || 'document.pdf';
  const baseName = filename.replace(/\.[^.$]+$/, '');
  const title = sourceDoc.title || baseName;
  const tags = Array.isArray(sourceDoc.tags) ? sourceDoc.tags.join(', ') : '';
  const docType = sourceDoc.document_type || '';
  const content = sourceDoc.parsed_text || sourceDoc.text || '';

  const markdown = [
    `# ${title}`,
    '',
    `Quelle: ${filename}`,
    docType ? `Dokumenttyp: ${docType}` : '',
    tags ? `Tags: ${tags}` : '',
    '',
    '## Inhalt',
    '',
    content
  ].filter(Boolean).join('\n');

  const markdownFileName = `${baseName}.md`;

  return {
    json: {
      ...item.json,
      markdown_filename: markdownFileName,
      markdown_path: `/files/anythingllm/${markdownFileName}`,
      markdown_content: markdown,
    },
    binary: {
      data: {
        data: Buffer.from(markdown, 'utf8'),
        mimeType: 'text/markdown',
        fileName: markdownFileName,
      }
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const sourceDoc = item.json;

  const filename = sourceDoc.filename || 'document.pdf';
  const baseName = filename.replace(/\.[^.$]+$/, '');
  const title = sourceDoc.title || baseName;

  const docType = sourceDoc.document_type || sourceDoc.docType || '';
  const language = sourceDoc.language || '';
  const domain = sourceDoc.domain || '';
  const subdomain = sourceDoc.subdomain || '';
  const processedAt = sourceDoc.processed_at || '';

  const content = sourceDoc.parsed_text || sourceDoc.text || sourceDoc.content || '';

  const tags = Array.isArray(sourceDoc.tags) ? sourceDoc.tags : [];
  const keywords = Array.isArray(sourceDoc.keywords) ? sourceDoc.keywords : [];
  const methods = Array.isArray(sourceDoc.methods) ? sourceDoc.methods : [];

  let tagsSection = '';
  if (tags.length > 0) {
    const tagLines = tags.map(tag => `- ${tag}`);
    tagsSection = ['## Tags', '', ...tagLines, ''].join('\n');
  }

  let keywordsSection = '';
  if (keywords.length > 0) {
    const keywordLines = keywords.map(keyword => `- ${keyword}`);
    keywordsSection = ['## Keywords', '', ...keywordLines, ''].join('\n');
  }

  let methodsSection = '';
  if (methods.length > 0) {
    const methodLines = methods.map(method => `- ${method}`);
    methodsSection = ['## Methoden', '', ...methodLines, ''].join('\n');
  }

  const metaLines = [
    `Quelle: ${filename}`,
    docType ? `Dokumenttyp: ${docType}` : '',
    language ? `Sprache: ${language}` : '',
    domain ? `Domain: ${domain}` : '',
    subdomain ? `Subdomain: ${subdomain}` : '',
    processedAt ? `Verarbeitet am: ${processedAt}` : '',
  ].filter(Boolean);

  const markdown = [
    `# ${title}`,
    '',
    ...metaLines,
    '',
    tagsSection,
    keywordsSection,
    methodsSection,
    '## Inhalt',
    '',
    content
  ].filter(Boolean).join('\n');

  const markdownFileName = `${baseName}.md`;

  return {
    json: {
      ...item.json,
      markdown_filename: markdownFileName,
      markdown_path: `/files/anythingllm/${markdownFileName}`,
      markdown_content: markdown,
    },
    binary: {
      data: {
        data: Buffer.from(markdown, 'utf8'),
        mimeType: 'text/markdown',
        fileName: markdownFileName,
      }
    }
  };
});

// Reine Umformung - die Markdown-Datei hat der Dienst gebaut.
// Hier wird nur in das Format gebracht, das der Master-Ablauf erwartet.
// Bewusst ohne Logik: Alles, was den Inhalt betrifft, steckt in
// mk_md.baue_markdown() und gilt damit fuer die Skript-Kette und fuer
// n8n gleichermassen.
return $input.all().map((item) => {
  const a = item.json;
  const name = a.dateiname || 'dokument.md';
  return {
    json: {
      markdown_filename: name,
      markdown_path: '/files/anythingllm/' + name,
      markdown_content: a.markdown,
      zeichen: a.zeichen,
      seiten: a.seiten,
      tags: a.tags,
      keywords: a.keywords,
      methoden: a.methoden,
    },
    binary: {
      data: {
        data: Buffer.from(a.markdown, 'utf8').toString('base64'),
        mimeType: 'text/markdown',
        fileName: name,
      },
    },
  };
});
